import json, glob, os
import numpy as np
from collections import Counter

CATS = ['True', 'False', 'Unknown']

def normalize_answer(ans, categories=CATS):
    if ans is None: return None
    s = str(ans).strip()
    if not s: return None
    m = {c.lower(): c for c in categories}
    if s.lower() in m: return m[s.lower()]
    return 'Unknown'

intdir = 'results/exp055_multitemp_mistral_folio/intermediates'
files = sorted(glob.glob(os.path.join(intdir, '*.json')))

# Collect per-temperature votes AND compute SC
temp_data = {}  # temp -> {'votes': [], 'correct': 0, 'total': 0}
for fpath in files:
    with open(fpath) as f:
        data = json.load(f)
    gt = data.get('problem', {}).get('answer', None)
    gt_norm = normalize_answer(gt) if gt else None
    sr = data.get('sica_result', {})
    traces = sr.get('traces', [])

    temp_groups = {}
    for t in traces:
        temp = t.get('temperature', None)
        if temp is not None:
            temp_groups.setdefault(temp, []).append(t)

    for temp, group in temp_groups.items():
        if temp not in temp_data:
            temp_data[temp] = {'votes': [], 'correct': 0, 'total': 0}
        vote_counter = Counter()
        for t in group:
            a = normalize_answer(t.get('answer', None))
            if a is not None:
                vote_counter[a] += 1
        if vote_counter:
            majority = vote_counter.most_common(1)[0][0]
            temp_data[temp]['total'] += 1
            if gt_norm and majority == gt_norm:
                temp_data[temp]['correct'] += 1

for temp in sorted(temp_data.keys()):
    td = temp_data[temp]
    sc_pct = td['correct'] / td['total'] * 100 if td['total'] > 0 else 0
    print(f'T={temp}: SC={sc_pct:.2f}% ({td[\"correct\"]}/{td[\"total\"]})')
"

